function topologicalSortKahn(nodeCount, edges) {
  const adj = Array.from({ length: nodeCount }, () => []);
  const inDegree = new Array(nodeCount).fill(0);

  for (const [before, after] of edges) {
    adj[before].push(after);
    inDegree[after]++;                 // one more thing blocking it
  }

  const ready = [];
  for (let v = 0; v < nodeCount; v++) if (inDegree[v] === 0) ready.push(v);

  const order = [];
  while (ready.length > 0) {
    const v = ready.pop();
    order.push(v);
    for (const next of adj[v]) {
      if (--inDegree[next] === 0) ready.push(next);
    }
  }

  // Anything left un-emitted is stuck behind a cycle.
  return order.length === nodeCount ? order : null;
}

function topologicalSortDFS(nodeCount, edges) {
  const adj = Array.from({ length: nodeCount }, () => []);
  for (const [before, after] of edges) adj[before].push(after);

  const NEW = 0, OPEN = 1, DONE = 2;
  const state = new Array(nodeCount).fill(NEW);
  const finished = [];

  function visit(v) {
    state[v] = OPEN;                   // still inside v's call
    for (const next of adj[v]) {
      if (state[next] === OPEN) return false;   // edge back into the call stack: a cycle
      if (state[next] === NEW && !visit(next)) return false;
    }
    state[v] = DONE;
    finished.push(v);                  // everything after v is already in the list
    return true;
  }

  for (let v = 0; v < nodeCount; v++) {
    if (state[v] === NEW && !visit(v)) return null;
  }
  return finished.reverse();
}

