def topological_sort_dfs(node_count, edges):
    adj = [[] for _ in range(node_count)]
    for before, after in edges:
        adj[before].append(after)

    NEW, OPEN, DONE = 0, 1, 2
    state = [NEW] * node_count
    finished = []

    def visit(v):
        state[v] = OPEN                # still inside v's call
        for nxt in adj[v]:
            if state[nxt] == OPEN:
                return False           # edge back into the call stack: a cycle
            if state[nxt] == NEW and not visit(nxt):
                return False
        state[v] = DONE
        finished.append(v)             # everything after v is already in the list
        return True

    for v in range(node_count):
        if state[v] == NEW and not visit(v):
            return None
    return finished[::-1]
